import java.util.function.BiFunction;

public class Main {
  // La forma genérica de "envolver" lógica en Java es usando interfaces funcionales:
  static BiFunction<Integer, Integer, Integer> misuma = (x, y) -> x + y;

  public static void main(String[] args) {
      int[] x = {1, 2, 3, 4};
      int[] y = {5, 6, 7, 8};
      int[] resultado = new int[4];

      // Lamentablemente, la interfaz de Java no vectoriza en SIMD automáticamente. 
      // Simplemente provee Programación Funcional, requiriendo un bucle.
      for(int i = 0; i < 4; i++) {
          resultado[i] = misuma.apply(x[i], y[i]);
      }
  }
}
